"""One ordered append-only evidence writer; run IDs are generated by runtime."""
import json
import time
from datetime import datetime, timezone
from pathlib import Path


class EventLog:
    def __init__(self, run_id, directory: Path, *, started=None):
        directory.mkdir(parents=True, exist_ok=True)
        self.path = directory / f"{run_id}.jsonl"
        self.run_id = run_id
        self.started = started if started is not None else time.monotonic()
        self.sequence = 0
        self.scenario_version = None
        self.scenario_hash = None
        self.events = []
        self._file = self.path.open("x", encoding="utf-8")

    def emit(self, kind, payload=None, *, proposal_id=None):
        self.sequence += 1
        event = {"protocol_version": "1.0", "run_id": self.run_id, "sequence": self.sequence,
                 "timestamp": datetime.now(timezone.utc).isoformat(),
                 "elapsed_ms": int((time.monotonic() - self.started) * 1000),
                 "scenario_version": self.scenario_version, "scenario_hash": self.scenario_hash,
                 "proposal_id": proposal_id, "type": kind, "payload": payload or {}}
        self.events.append(event)
        self._file.write(json.dumps(event, ensure_ascii=True, separators=(",", ":")) + "\n")
        self._file.flush()

    def close(self):
        self._file.close()
